<?php $this->extend('App\Modules\Admin\Views\layout'); $this->section('content'); ?>
<div class="mb-6"><h1 class="text-2xl font-semibold text-gray-100">Portal Analytics</h1><p class="mt-1 text-sm text-gray-400">Engagement and registration data recorded by the portal.</p></div>
<div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><?php foreach ([['Portal users',$users],['Attendee profiles',$attendees],['Emergence 2026 registrations',$registered2026],['Unique session viewers',$uniqueSessionViewers],['Session ratings',$ratings],['Average rating',$ratings ? number_format($averageRating, 1) . ' / 5' : '—']] as [$label,$value]): ?><div class="rounded-lg border border-gray-700 bg-gray-800 p-4"><span class="text-xs uppercase tracking-wide text-gray-400"><?php echo esc($label); ?></span><strong class="mt-2 block text-2xl text-white"><?php echo esc((string) $value); ?></strong></div><?php endforeach; ?></div>
<div class="mt-6 grid gap-6 xl:grid-cols-2"><section class="rounded-lg border border-gray-700 bg-gray-800 p-5"><h2 class="font-semibold text-gray-100">Attendees by country</h2><div class="mt-4 space-y-2"><?php foreach ($countries as $country): ?><div class="flex justify-between border-b border-gray-700 pb-2 text-sm"><span class="text-gray-300"><?php echo esc($country['country']); ?></span><strong class="text-white"><?php echo (int) $country['total']; ?></strong></div><?php endforeach; ?><?php if (!$countries): ?><p class="text-sm text-gray-400">No country data recorded yet.</p><?php endif; ?></div></section><section class="rounded-lg border border-gray-700 bg-gray-800 p-5"><h2 class="font-semibold text-gray-100">Most-rated sessions</h2><p class="mt-1 text-xs text-gray-400">Ratings measure attendee feedback, not video watch duration.</p><div class="mt-4 space-y-2"><?php foreach ($sessions as $session): ?><div class="border-b border-gray-700 pb-2 text-sm"><div class="flex justify-between gap-3"><span class="text-gray-200"><?php echo esc($session['sessions_name'] ?: 'Session'); ?></span><strong class="text-amber-300"><?php echo number_format((float) $session['average_rating'], 1); ?>/5</strong></div><span class="text-xs text-gray-400"><?php echo (int) $session['ratings_count']; ?> rating(s)</span></div><?php endforeach; ?><?php if (!$sessions): ?><p class="text-sm text-gray-400">No session ratings recorded yet.</p><?php endif; ?></div></section></div>
<section class="mt-6 rounded-lg border border-gray-700 bg-gray-800 p-5"><h2 class="font-semibold text-gray-100">Exhibitor engagement</h2><p class="mt-1 text-xs text-gray-400">Recorded booth views and likes.</p><div class="mt-4 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-gray-700 text-xs uppercase text-gray-400"><tr><th class="p-2">Exhibitor</th><th class="p-2">Views</th><th class="p-2">Likes</th></tr></thead><tbody><?php foreach ($exhibitors as $exhibitor): ?><tr class="border-b border-gray-800"><td class="p-2 text-gray-200"><?php echo esc($exhibitor['exhibitor_name'] ?? 'Exhibitor'); ?></td><td class="p-2"><?php echo (int) ($exhibitor['views'] ?? 0); ?></td><td class="p-2"><?php echo (int) ($exhibitor['likes'] ?? 0); ?></td></tr><?php endforeach; ?><?php if (!$exhibitors): ?><tr><td colspan="3" class="p-4 text-gray-400">No exhibitor engagement data recorded yet.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="mt-6 rounded-lg border border-gray-700 bg-gray-800 p-5"><h2 class="font-semibold text-gray-100">Most-viewed sessions</h2><p class="mt-1 text-xs text-gray-400">Each logged-in attendee is counted once per session when they open its session page. This is portal session-view data, not external Zoom or LivePush watch duration.</p><div class="mt-4 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-gray-700 text-xs uppercase text-gray-400"><tr><th class="p-2">Session</th><th class="p-2 text-right">Unique viewers</th></tr></thead><tbody><?php foreach ($viewedSessions as $viewedSession): ?><tr class="border-b border-gray-800"><td class="p-2 text-gray-200"><?php echo esc($viewedSession['sessions_name'] ?: 'Session'); ?></td><td class="p-2 text-right font-semibold text-white"><?php echo (int) $viewedSession['viewer_count']; ?></td></tr><?php endforeach; ?><?php if (!$viewedSessions): ?><tr><td colspan="2" class="p-4 text-gray-400">No session-page views recorded yet.</td></tr><?php endif; ?></tbody></table></div></section>
<p class="mt-6 text-xs text-gray-500">Gender, verified livestream watch duration, and session likes are not collected by the portal, so they are intentionally not reported.</p>
